#include <Arduino.h>
QueueHandle_t readings;

void producer(void*) {
  int value = 0;
  for (;;) {
    xQueueSend(readings, &value, portMAX_DELAY);
    ++value;
    vTaskDelay(pdMS_TO_TICKS(500));
  }
}

void setup() {
  Serial.begin(115200);
  readings = xQueueCreate(4, sizeof(int));
  configASSERT(readings);
  xTaskCreate(producer, "sensor", 2048, nullptr, 1, nullptr);
}

void loop() {
  int value;
  if (xQueueReceive(readings, &value, portMAX_DELAY))
    Serial.println(value);
}
